SELECT siz_cd, count(*) FROM t_prc_component_prices
 WHERE comp_cd = 'STK_KISSCUT_PRINT' AND siz_cd IN ('SIZ_000057', 'SIZ_000058', 'SIZ_000067')
 GROUP BY 1 ORDER BY 1;

